"""Chapter summaries generated by the summariser LoRA via vLLM, with caching and validation."""

from __future__ import annotations

import hashlib
import json
import re
from collections.abc import Sequence
from typing import Protocol

from storygraph.genai.prompts import SUMMARY_SYSTEM, SUMMARY_USER
from storygraph.schemas import ChapterSummary, ContentSignals, Segment, Title

_JSON_RE = re.compile(r"\{.*\}", re.DOTALL)
_SPOILER_PATTERNS = re.compile(
    r"\b(turns out|in the end|finally (?:dies|reveals|discovers)|is revealed to be|the (?:killer|murderer) (?:is|was)|ends with)\b",
    re.IGNORECASE,
)


class TextLLM(Protocol):
    def complete(self, system: str, user: str, max_tokens: int = 256) -> str: ...


class SummaryCache(Protocol):
    def get(self, key: str) -> str | None: ...

    def set(self, key: str, value: str, ttl_s: int) -> None: ...


class DictCache:
    def __init__(self) -> None:
        self._d: dict[str, str] = {}

    def get(self, key: str) -> str | None:
        return self._d.get(key)

    def set(self, key: str, value: str, ttl_s: int) -> None:
        self._d[key] = value


def cache_key(segment: Segment, model_version: str) -> str:
    return hashlib.sha1(
        f"{model_version}|{segment.title_id}|{segment.index}|{len(segment.text)}".encode()
    ).hexdigest()


def has_spoiler_markers(summary: str) -> bool:
    return bool(_SPOILER_PATTERNS.search(summary))


def parse_summary(raw: str, title_id: str, index: int) -> ChapterSummary:
    m = _JSON_RE.search(raw)
    if not m:
        raise ValueError("no JSON in summary output")
    d = json.loads(m.group(0))
    heading = str(d.get("heading", "")).strip()[:80] or f"Chapter {index + 1}"
    summary = " ".join(str(d.get("summary", "")).split())[:1200]
    return ChapterSummary(
        title_id=title_id,
        segment_index=index,
        heading=heading,
        summary=summary,
        spoiler_free=not has_spoiler_markers(summary),
    )


class ChapterSummariser:
    def __init__(
        self,
        llm: TextLLM,
        cache: SummaryCache | None = None,
        model_version: str = "summariser-lora/v3",
        ttl_s: int = 86400,
        max_chars: int = 16_000,
    ):
        self.llm = llm
        self.cache = cache or DictCache()
        self.model_version = model_version
        self.ttl_s = ttl_s
        self.max_chars = max_chars

    def summarise(
        self, title: Title, segment: Segment, signals: ContentSignals | None, total: int
    ) -> ChapterSummary:
        key = cache_key(segment, self.model_version)
        cached = self.cache.get(key)
        if cached:
            return ChapterSummary.model_validate_json(cached)
        text = (
            segment.text
            if len(segment.text) <= self.max_chars
            else segment.text[: self.max_chars] + " …"
        )
        user = SUMMARY_USER.format(
            title=title.title,
            kind=title.kind.value,
            index=segment.index + 1,
            total=total,
            minutes=(segment.end - segment.start) / 60,
            genres=", ".join(signals.label_names("genres")) if signals else "unknown",
            moods=", ".join(signals.label_names("moods")) if signals else "unknown",
            text=text,
        )
        raw = self.llm.complete(SUMMARY_SYSTEM, user, max_tokens=220)
        out = parse_summary(raw, title.title_id, segment.index)
        if not out.spoiler_free:
            # one retry with an explicit instruction, then fall back to a heading-only summary
            raw = self.llm.complete(
                SUMMARY_SYSTEM + " The previous draft contained a spoiler; remove it.",
                user,
                max_tokens=220,
            )
            out = parse_summary(raw, title.title_id, segment.index)
            if not out.spoiler_free:
                out = ChapterSummary(
                    title_id=title.title_id,
                    segment_index=segment.index,
                    heading=out.heading,
                    summary="",
                    spoiler_free=True,
                )
        self.cache.set(key, out.model_dump_json(), self.ttl_s)
        return out

    def summarise_title(
        self,
        title: Title,
        segments: Sequence[Segment],
        signals: Sequence[ContentSignals] | None = None,
    ) -> list[ChapterSummary]:
        return [
            self.summarise(title, s, signals[i] if signals else None, len(segments))
            for i, s in enumerate(segments)
        ]
